import React, { useState, useEffect } from 'react';
import BookCard from './BookCard/BookCard';
import Filters from '../Filters/Filters';
import Loader from '../Loader/Loader';
import { getProducts } from '../../api/axiosConfig';
import './BooksList.css';

function BooksList({ searchTerm }) {
    const [books, setBooks] = useState([]);
    const [filters, setFilters] = useState({ price: '', pages: '', genre: '', search: '' });
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    const fetchBooks = async (appliedFilters) => {
        setLoading(true);
        setError(null);
        try {
            const response = await getProducts(appliedFilters);
            setBooks(response.data);
        } catch (error) {
            setError(error.message);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        // Об'єднуємо пошук з фільтрами
        const appliedFilters = { ...filters, search: searchTerm || '' };
        fetchBooks(appliedFilters);
    }, [filters, searchTerm]);

    const handleFilterChange = (selectedFilters) => {
        setFilters(selectedFilters);
    };

    return (
        <div>
            <Filters onFilterChange={handleFilterChange} />
            {loading && <Loader />}
            {error && <p className="error">{error}</p>}
            {!loading && !error && (
                <div className="books-list">
                    {books.map((book) => (
                        <BookCard
                            key={book.id}
                            id={book.id}
                            name={book.title}
                            pages={book.pages}
                            genre={book.genre}
                            image={book.image}
                            price={book.price}
                            description={book.description}
                        />
                    ))}
                </div>
            )}
        </div>
    );
}

export default BooksList;
